"""ft-v2 plan validator, COMMON to every arm (final test, stage H-B1; PACKAGE-SPEC section 4, decision D3).

It keeps every acceptance rule of ``step4_gemma.validate`` (the ft-v1 validator), so a plan ft-v1 accepts is still
accepted -- with ONE documented exception, ``E_SELF_TARGET`` (``pick_and_place X to X``: the executor can only fail) --
and adds:

  * a closed set of machine codes (``CODES``); every error is ``{"i", "code", "reason"}``;
  * the hand trace follows the FROZEN executor contract ``exec_contract.json`` (generated by
    ``build_exec_contract`` from ``honest_skills`` + ``step4_gemma``, never typed by hand);
  * ``unknown``: object types of the plan that are not in ``observed_types`` (the current observation summary). That is
    INFORMATION for the log, never an error and never mentioned to the planner: a type may exist in the kitchen and not
    have been seen yet (hidden state is UNKNOWN, not wrong);
  * a repair text built ONLY from a fixed template per code, the step index, the arm's OWN plan tokens and names taken
    from the tool list / type vocabulary (``TEMPLATE_FIELDS`` is checked statically by the selftest). No scene fact,
    never "absent" / "not in this kitchen". The cutting-tool rule (A26: slice needs a held ButterKnife) is an EXECUTOR
    refusal (no_cutting_tool), not a rule here: no repair code, the plan is accepted and the executor refuses (A26 3(c)).

Pure module: no simulator, no network. ``honest_skills`` / ``step4_gemma`` / ``agent_llm`` are imported lazily (sim/
must be on ``sys.path``, like every sim module).
"""
from __future__ import annotations

import difflib
import hashlib
import json
import os
import re
import string
from typing import Optional

HERE = os.path.dirname(os.path.abspath(__file__))
EXEC_CONTRACT_PATH = os.path.join(HERE, "exec_contract.json")
FT_V2_PATH = os.path.join(HERE, "ft_v2.json")
MAX_STEPS = 12

CODES = ("E_NO_PLAN", "E_EMPTY", "E_TOO_LONG", "E_STEP_SHAPE", "E_SCHEMA", "E_UNKNOWN_TOOL", "E_SIGNATURE_AS_ACTION",
         "E_UNKNOWN_TYPE", "E_MISSING_OBJECT", "E_EXTRA_TO", "E_MISSING_TO", "E_BAD_ARG", "E_HAND_FULL",
         "E_HAND_EMPTY", "E_SELF_TARGET")

#: the fixed repair sentence per code. Free fields (and ONLY these) may be filled, from the plan / vocabulary / tool list.
TEMPLATES = {
    "E_NO_PLAN": "the reply is not a JSON plan ({detail}); reply with {{\"say\": \"...\", \"plan\": [ ...steps... ]}}",
    "E_EMPTY": "the plan is empty; write at least one step",
    "E_TOO_LONG": "the plan has {n} steps; at most {max} are allowed",
    "E_STEP_SHAPE": "a step must be a JSON object with the keys action, object, to, arg",
    "E_SCHEMA": "the reply does not have the required shape ({detail})",
    "E_UNKNOWN_TOOL": "unknown action {action!r} (not in the tool list); choose one of: {tools}",
    "E_SIGNATURE_AS_ACTION": "{action!r} puts the arguments inside \"action\"; write the tool name alone in "
                             "\"action\" and the type in \"object\", for example {example}",
    "E_UNKNOWN_TYPE": "unknown object type {value!r} in '{field}' (not in the detector's type list); write a type "
                      "exactly as spelled in that list{suggest}",
    "E_MISSING_OBJECT": "{tool} needs 'object' (an object type from the type list)",
    "E_MISSING_TO": "{tool} needs 'to' (an object type from the type list); with no destination use pickup instead",
    "E_EXTRA_TO": "{tool} takes no 'to' here (the plan predicts {held} at this step). To move an item to a receptacle "
                  "use pick_and_place with 'object' = the item and 'to' = the receptacle; put_in is only for a held "
                  "item and its 'object' is the receptacle",
    "E_BAD_ARG": "fill arg must be one of {liquids}, not {value!r}",
    "E_HAND_FULL": "{tool} {value} while already holding {held} (put it somewhere or drop it first)",
    "E_HAND_EMPTY": "{tool} needs a held object, but the hand is empty at this step; pick the item up first (pickup) "
                    "or use pick_and_place",
    "E_SELF_TARGET": "{tool}: 'object' and 'to' are both {value!r}; the object must go to a different receptacle",
}
#: every free field a template may use; each is filled from the plan's own tokens, the tool list or the vocabulary
ALLOWED_FIELDS = frozenset({"detail", "n", "max", "action", "tools", "example", "value", "field", "suggest", "tool",
                            "held", "liquids"})
TEMPLATE_FIELDS = {c: {f for _, f, _, _ in string.Formatter().parse(t) if f} for c, t in TEMPLATES.items()}

#: tools whose plan step opens a closed container by itself (SYSTEM rule + TOOL_SPECS meanings of ft-v1)
OPENS_ITSELF = frozenset({"pickup", "put_in", "pick_and_place", "heat", "cook", "go_to", "search_for"})
#: tools that do not move the agent
NO_WALK = frozenset({"drop", "crouch", "stand"})
#: tools that touch neither the hand nor an object state
HAND_NONE = frozenset({"go_to", "search_for", "close_all", "crouch", "stand"})
NOTES = {
    "heat": "heat and cook both use the Microwave; the food ends in hand",
    "cook": "heat and cook both use the Microwave; the food ends in hand",
    "slice": "slice needs a held ButterKnife (the only cutting tool); without it the executor refuses (no_cutting_tool)",
    "wash": "wash puts the item in the sink basin and leaves it there",
    "put_in": "object is the receptacle; the held item is not named",
    "pick_and_place": "walks to the object, searches and opens containers itself, then puts it into / onto `to`",
    "pickup": "a pickup of the type already in hand is a no-op",
    "fill": "arg is one of the liquids; no arg means water",
    "close_all": "closes every container the agent itself saw open",
}


def _canonical(obj) -> str:
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def sha_of(obj: dict) -> str:
    """sha256 of the canonical JSON of ``obj`` without its own 'sha256' key (same convention as common.self_sha)."""
    return hashlib.sha256(_canonical({k: v for k, v in obj.items() if k != "sha256"}).encode("utf-8")).hexdigest()


def _src_sha16(path: str) -> str:
    with open(path, "rb") as f:
        return hashlib.sha256(f.read().replace(b"\r\n", b"\n")).hexdigest()[:16]


# ------------------------------------------------------------------------------------------------ executor contract
def _meaning_v2(what: str, requires_tool) -> str:
    """The ft-v2 meaning (shared tool line, every arm, same bytes). A tool that needs a type in hand says so, GENERATED from
    ``requires_tool`` (= honest_skills.CUTTING_TOOLS for slice), never typed per type. BK-LINE 2026-10-13 (Arash decision (1)
    "butter-knife rule for every arm = YES"; Astra docs/final-test/_astra/BK-LINE.txt): "slice it" ->
    "slice it; you must be holding a ButterKnife". ft-v1 (step4_gemma.TOOL_SPECS, the frozen step-4 text) is unchanged."""
    if not requires_tool:
        return what
    return what + "; you must be holding a " + " or a ".join(requires_tool)


def build_exec_contract() -> dict:
    """The authoritative tool effects, GENERATED from ``honest_skills`` (tool list, liquids) and ``step4_gemma`` (argument
    rules, hand effects). ``pkg.exec/1``."""
    import honest_skills as hs
    import step4_gemma as g
    tools = {}
    for t in sorted(hs.TOOLS):
        o, to, arg, what = g.TOOL_SPECS[t]
        req = sorted(hs.CUTTING_TOOLS) if t == "slice" and getattr(hs, "CUT_RULE_ON", False) else []
        eff = g.HAND.get(t)
        hand = {"take": "take", "take-release": "take-release", "need": "release"}.get(eff) \
            or ("none" if t in HAND_NONE else "keep")
        tools[t] = {"object": {"type": "type", "opt": "opt"}.get(o, "none"), "to": "type" if to == "type" else "none",
                    "arg": list(hs.LIQUIDS) if arg == "liquid" else "none", "hand": hand,
                    "requires_held": eff == "need",
                    "requires_empty_hand": eff in ("take", "take-release"),
                    "walks_itself": t not in NO_WALK, "opens_itself": t in OPENS_ITSELF,
                    "ends_in_hand": eff == "take", "meaning": _meaning_v2(what, req), "notes": NOTES.get(t, ""),
                    # A26 item 2 (K-B2b): the tool types the executor needs in hand (read from honest_skills; the
                    # validator does NOT enforce it, A26 3(c): no new repair code; the executor refuses)
                    "requires_tool": req}
    out = {"schema": "pkg.exec/1",
           "derived_from": {"honest_skills": _src_sha16(hs.__file__), "step4_gemma": _src_sha16(g.__file__)},
           "tools": tools}
    out["sha256"] = sha_of(out)
    return out


_CONTRACT: Optional[dict] = None
_CFG: Optional[dict] = None


def exec_contract() -> dict:
    global _CONTRACT
    if _CONTRACT is None:
        with open(EXEC_CONTRACT_PATH, encoding="utf-8") as f:
            _CONTRACT = json.load(f)
    return _CONTRACT


def ft_v2_config() -> dict:
    global _CFG
    if _CFG is None:
        with open(FT_V2_PATH, encoding="utf-8") as f:
            _CFG = json.load(f)
    return _CFG


def _deps():
    import honest_skills as hs
    import step4_gemma as g
    return hs, g


# ------------------------------------------------------------------------------------------------ repair text
def suggest_type(value, types) -> str:
    """' (did you mean 'Fridge'?)' from the vocabulary by spelling only; '' when off or no close name."""
    if not ft_v2_config().get("suggest_types", False) or not isinstance(value, str) or not value.strip():
        return ""
    best = difflib.get_close_matches(value.strip(), sorted(types), n=1, cutoff=float(ft_v2_config().get("suggest_cutoff", 0.75)))
    return f" (did you mean {best[0]!r}?)" if best else ""


def reason(code: str, **kw) -> str:
    fields = TEMPLATE_FIELDS[code]
    miss = fields - set(kw)
    if miss:
        raise KeyError(f"{code}: missing fields {sorted(miss)}")
    return TEMPLATES[code].format(**{k: kw[k] for k in fields})


def _err(i, code, **kw) -> dict:
    return {"i": i, "code": code, "reason": reason(code, **kw)}


def _held_text(hand) -> str:
    return f"you hold {hand}" if hand else "an empty hand"


def _example(action: str, obj) -> str:
    return json.dumps({"action": action, "object": obj}, ensure_ascii=False)


# ------------------------------------------------------------------------------------------------ validation
def validate(obj: dict, types, holding: Optional[str] = None, tools=None, observed_types=None) -> dict:
    """Whole-plan validation. -> ``{ok, steps (normalised), errors [{i, code, reason}], codes, notes, normalised,
    unknown [{i, type}]}``. ``observed_types`` (optional) only fills ``unknown``."""
    hs, g = _deps()
    con = exec_contract()["tools"]
    tool_set = set(tools or hs.TOOLS)
    types = set(types)
    tool_names = ", ".join(sorted(tool_set))
    errors, notes, steps, normalised, unknown = [], [], [], [], []

    def done():
        return {"ok": not errors, "steps": steps, "errors": errors, "codes": [e["code"] for e in errors],
                "notes": notes, "normalised": normalised, "unknown": unknown}

    plan = obj.get("plan") if isinstance(obj, dict) else None
    if not isinstance(plan, list):
        errors.append(_err(None, "E_NO_PLAN", detail="no 'plan' list in the reply"))
        return done()
    if not plan:
        errors.append(_err(None, "E_EMPTY"))
    if len(plan) > MAX_STEPS:
        errors.append(_err(None, "E_TOO_LONG", n=len(plan), max=MAX_STEPS))
    hand = holding
    for i, st in enumerate(plan):
        if not isinstance(st, dict):
            errors.append(_err(i, "E_STEP_SHAPE"))
            continue
        raw_a = str(st.get("action") or "").strip()
        a = raw_a.lower().replace(" ", "_").replace("-", "_")
        a = hs.ALIASES.get(a, a)
        if a != raw_a:
            notes.append(f"step {i}: action {raw_a!r}->{a}")
        raw_step = {"action": raw_a, "object": st.get("object"), "to": st.get("to"), "arg": st.get("arg")}
        if a not in tool_set:
            m = re.match(r"^\s*([A-Za-z_]+)\s*\((.*)\)\s*$", raw_a)
            if m and hs.ALIASES.get(m.group(1).lower(), m.group(1).lower()) in tool_set:
                errors.append(_err(i, "E_SIGNATURE_AS_ACTION", action=raw_a,
                                   example=_example(m.group(1), m.group(2).strip())))
            else:
                errors.append(_err(i, "E_UNKNOWN_TOOL", action=raw_a, tools=tool_names))
            steps.append(raw_step)
            continue
        # ---- ft-v1's two normalisations (kept; recorded) -------------------------------------------------
        if a == "pickup" and st.get("to") not in (None, ""):
            o_val, _ = g._canon(st.get("object"), types)
            t_val, t_note = g._canon(st.get("to"), types)
            if t_val is None or t_note == "unknown":
                errors.append(_err(i, "E_EXTRA_TO", tool="pickup", held=_held_text(hand)))
                steps.append(dict(raw_step, action=a))              # ft-v1 parity: the normalised action name
                continue
            normalised.append({"i": i, "from": {"action": a, "object": o_val, "to": t_val},
                               "to": {"action": "pick_and_place", "object": o_val, "to": t_val}})
            notes.append(f"step {i}: pickup {o_val} to {t_val} -> pick_and_place {o_val} {t_val} (a pickup with a "
                         "destination)")
            a = "pick_and_place"
        c = con[a]
        norm = {"action": a, "object": None, "to": None, "arg": None}
        if a == "put_in" and st.get("to") not in (None, ""):
            o_val, _ = g._canon(st.get("object"), types)
            t_val, t_note = g._canon(st.get("to"), types)
            if t_val is None or t_note == "unknown":
                errors.append(_err(i, "E_UNKNOWN_TYPE", value=st.get("to"), field="to",
                                   suggest=suggest_type(st.get("to"), types)))
                steps.append(dict(raw_step, action=a))              # ft-v1 parity: the normalised action name
                continue
            if hand and o_val == hand:
                normalised.append({"i": i, "from": {"action": a, "object": o_val, "to": t_val},
                                   "to": {"action": a, "object": t_val, "to": None}})
                notes.append(f"step {i}: put_in {o_val} to {t_val} -> put_in {t_val} "
                             f"(the plan predicts you hold {o_val}; put_in takes the receptacle)")
                st = dict(st, object=t_val, to=None)
            else:
                errors.append(_err(i, "E_EXTRA_TO", tool="put_in", held=_held_text(hand)))
                steps.append(dict(raw_step, action=a))
                continue
        for field in ("object", "to"):
            rule = c[field]
            val, note = g._canon(st.get(field), types)
            if rule == "type":
                if val is None:
                    errors.append(_err(i, "E_MISSING_OBJECT" if field == "object" else "E_MISSING_TO", tool=a))
                elif note == "unknown":
                    errors.append(_err(i, "E_UNKNOWN_TYPE", value=val, field=field, suggest=suggest_type(val, types)))
                else:
                    if note:
                        notes.append(f"step {i}: {field} {note}")
                    if observed_types is not None and val not in observed_types:
                        unknown.append({"i": i, "type": val})
                norm[field] = val
            elif rule == "opt":
                if val is not None and note != "unknown":
                    norm[field] = val
            elif val is not None:
                notes.append(f"step {i}: {a} takes no '{field}'; {val!r} ignored")
        if c["arg"] != "none":
            liq = str(st.get("arg") or "water").strip().lower()
            if liq not in c["arg"]:
                errors.append(_err(i, "E_BAD_ARG", liquids=", ".join(c["arg"]), value=liq))
            norm["arg"] = liq
        if a == "pick_and_place" and norm["object"] is not None and norm["object"] == norm["to"]:
            errors.append(_err(i, "E_SELF_TARGET", tool=a, value=norm["object"]))
        # ---- hand trace (the plan's own consequences, from what the agent was told it holds) ---------------
        if c["requires_empty_hand"] and hand and hand != norm["object"]:
            errors.append(_err(i, "E_HAND_FULL", tool=a, value=norm["object"] or "(no object)", held=hand))
        if c["requires_held"] and not hand:
            errors.append(_err(i, "E_HAND_EMPTY", tool=a))
        h = c["hand"]
        if h == "take":
            hand = norm["object"]
        elif h in ("take-release", "release"):
            hand = None
        steps.append(norm)
    return done()


def v1_validate(obj, types, holding=None, tools=None) -> dict:
    """The ft-v1 validator, for parity checks and for arms still on ft-v1."""
    return _deps()[1].validate(obj, types, holding, tools)


def _write_json(path, obj):
    with open(path, "w", encoding="utf-8", newline=chr(10)) as f:
        f.write(json.dumps(obj, indent=1, ensure_ascii=False) + chr(10))


def write_artifacts() -> dict:
    """Regenerate ``exec_contract.json`` and ``ft_v2.json`` (the pinned ft-v2 config + the sha of every frozen text).
    Run after any change to the texts: ``python sim/planners/validator_v2.py --write``."""
    from . import contract
    global _CONTRACT, _CFG
    con = build_exec_contract()
    _write_json(EXEC_CONTRACT_PATH, con)
    _CONTRACT = None
    old = ft_v2_config() if os.path.exists(FT_V2_PATH) else {}
    cfg = {"schema": "pkg.ft_v2/1", "version": "ft-v2", "max_repairs": contract.MAX_REPAIRS_V2,
           "summary_limit": 40, "glossary_fa": bool(old.get("glossary_fa", False)),
           "suggest_types": bool(old.get("suggest_types", True)),
           "suggest_cutoff": float(old.get("suggest_cutoff", 0.75)),
           "error_order": "plan-level errors first; then step order; within a step: object, to, arg, hand trace",
           "exec_contract_sha256": con["sha256"], "texts_sha256": contract.ft_v2_texts_sha()}
    cfg["sha256"] = sha_of(cfg)
    _write_json(FT_V2_PATH, cfg)
    _CFG = None
    return cfg


if __name__ == "__main__":
    import sys
    sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    if "--write" in sys.argv:
        from planners import validator_v2 as _v
        print(json.dumps(_v.write_artifacts(), indent=1))
